vagem -->\n<div style=\"border: 1px solid #eaeaea; border-radius: 10px; padding: 12px; margin: 12px 0;\">\n<strong style=\"font-size: 19px;\">Cuidados e Lavagem</strong>\n<ul style=\"padding-left: 18px; margin: 8px 0;\">\n<li>Lavar em água fria utilizando detergente ou sabão neutro.</li>\n<li>Secar naturalmente, à sombra.</li>\n<li>Evitar usar máquina de secar ou lavagem a seco.</li>\n<li>Não passar com ferro elétrico diretamente sobre o tecido.</li>\n</ul>\n</div>\n<!-- Encerramento -->\n<p style=\"margin: 2rem 0;\"><strong>Ideal para pescarias e aventuras ao ar livre</strong>, a Camisa de Pesca BRK é a escolha certa para quem valoriza <strong>conforto, tecnologia e estilo</strong> em um só produto.</p>\n<!-- Direitos Autorais -->\n<p style=\"margin: 1.5rem 0 0;\">Nossas estampas são protegidas pela Lei de Direitos Autorais (Lei 9.610/98). <strong>A reprodução não autorizada está sujeita às penalidades legais. Copiar é crime!</strong></p>\n<div class=\"imagens\"><img alt=\"\"></div>\n</section>\n</div>", "mode_b_html": "", "mode_b_markdown": "", "prohibited_links": ["https://use-brk-images-s3.s3.us-east-1.amazonaws.com/1762348260739-uv_protection.svg"], "orphaned_variants": []}, {"id": 7553906212930, "title": "Camisa de Pesca Brk com Capuz Hybrid Snow com Proteção Solar UV50+", "handle": "camisa-de-pesca-brk-com-capuz-hybrid-snow-com-protecao-solar-uv50", "url": "https://www.brkfishing.com.br/products/camisa-de-pesca-brk-com-capuz-hybrid-snow-com-protecao-solar-uv50", "master_sku": "HYB016", "variants_skus": ["HYB016PP", "HYB016P", "HYB016M", "HYB016G", "HYB016GG", "HYB016G1", "HYB016G2"], "total_skus_count": 7, "affected_skus_count": 7, "is_out_of_standard": true, "standard_violations": ["5 foto(s) com erro 404 (links quebrados).", "5 link(s) externo(s) não autorizado(s)."], "category": "Camisas de Pesca UV", "archetype": "LINHAGEM_VESTUARIO", "price": "R$ 169,90", "image": "https://cdn.shopify.com/s/files/1/0628/1445/3826/files/HYB016_022a333f-8152-427a-a460-73ff