ro -->\n<div style=\"display: flex; align-items: center; gap: 10px; flex: 1; min-width: 180px;\" class=\"xtechpro\">\n<img loading=\"lazy\" height=\"55\" width=\"55\" alt=\"Tecido XTech Pro\" src=\"https://cdn.shopify.com/s/files/1/0628/1445/3826/files/XTECH-LOGO-PRETO.svg?v=1764159850\"> <span style=\"font-size: 15px;\"> <strong>Tecido XTech Pro®</strong> leve, confortável e de alta performance para uso outdoor. </span>\n</div>\n</div>\n<!-- Benefícios -->\n<div style=\"margin: 2.5rem 0;\" class=\"beneficios\">\n<strong style=\"font-size: 19px;\">Benefícios da Camisa de Pesca BRK</strong>\n<ul style=\"padding-left: 19px; margin: 18px 0;\">\n<li>\n<strong>Proteção Solar UV50+</strong> para pescarias em dias ensolarados.</li>\n<li>\n<strong>Tecido XTech Pro®</strong> com toque macio, leve e confortável.</li>\n<li>\n<strong>Tecnologia Antiodor</strong> que ajuda a reduzir odores durante o uso prolongado.</li>\n<li>Modelagem pensada para <strong>mobilidade e conforto</strong> nas atividades ao ar livre.</li>\n<li>\n<strong>Estampas exclusivas BRK</strong> com visual moderno e estiloso.</li>\n<li>\n<strong>Garantia de 1 ano</strong> e <strong>troca fácil e descomplicada</strong>.</li>\n</ul>\n</div>\n<!-- Especificações -->\n<div style=\"border: 1px solid #eaeaea; border-radius: 10px; padding: 12px; margin: 12px 0;\">\n<strong style=\"font-size: 19px;\">Especificações</strong>\n<ul style=\"padding-left: 18px; margin: 8px 0;\">\n<li>Tecido exclusivo <strong>XTech Pro®</strong> de alta performance.</li>\n<li>\n<strong>Proteção Solar UV50+</strong> para atividades sob o sol.</li>\n<li>Tecnologia <strong>Antiodor</strong> para maior conforto em longos períodos de uso.</li>\n<li>Tecido leve, de <strong>secagem rápida</strong> e fácil manutenção.</li>\n<li>Estampas exclusivas BRK com cores vivas e alta definição.</li>\n<li>Ideal para <strong>pescarias e aventuras outdoor</strong>.</li>\n</ul>\n</div>\n<!-- Cuidados e Lavagem -->\n<div style=\"border: 1px solid #eaeaea; border